PigeonInternalCodecSerializer::PigeonInternalCodecSerializer() {}

EncodableValue PigeonInternalCodecSerializer::ReadValueOfType(
  uint8_t type,
  ::flutter::ByteStreamReader* stream) const {
  switch (type) {
    case 129: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<ProbeOperation>(enum_arg_value));
      }
    case 130: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<ProbeInputMode>(enum_arg_value));
      }
    case 131: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<LifecycleOperation>(enum_arg_value));
      }
    case 132: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<LifecycleControlAction>(enum_arg_value));
      }
    case 133: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<LifecycleTrayAction>(enum_arg_value));
      }
    case 134: {
        return CustomEncodableValue(ProbeCommand::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 135: {
        return CustomEncodableValue(ProbeSnapshot::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 136: {
        return CustomEncodableValue(LifecycleCommand::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 137: {
        return CustomEncodableValue(LifecycleUiEvidence::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 138: {
        return CustomEncodableValue(LifecycleSnapshot::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    default:
      return ::flutter::StandardCodecSerializer::ReadValueOfType(type, stream);
    }
}

void PigeonInternalCodecSerializer::WriteValue(
  const EncodableValue& value,
  ::flutter::ByteStreamWriter* stream) const {
  if (const CustomEncodableValue* custom_value = std::get_if<CustomEncodableValue>(&value)) {
    if (custom_value->type() == typeid(ProbeOperation)) {
      stream->WriteByte(129);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<ProbeOperation>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(ProbeInputMode)) {
      stream->WriteByte(130);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<ProbeInputMode>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(LifecycleOperation)) {
      stream->WriteByte(131);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<LifecycleOperation>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(LifecycleControlAction)) {
      stream->WriteByte(132);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<LifecycleControlAction>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(LifecycleTrayAction)) {
      stream->WriteByte(133);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<LifecycleTrayAction>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(ProbeCommand)) {
      stream->WriteByte(134);
      WriteValue(EncodableValue(std::any_cast<ProbeCommand>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(ProbeSnapshot)) {
      stream->WriteByte(135);
      WriteValue(EncodableValue(std::any_cast<ProbeSnapshot>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(LifecycleCommand)) {
      stream->WriteByte(136);
      WriteValue(EncodableValue(std::any_cast<LifecycleCommand>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(LifecycleUiEvidence)) {
      stream->WriteByte(137);
      WriteValue(EncodableValue(std::any_cast<LifecycleUiEvidence>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(LifecycleSnapshot)) {
      stream->WriteByte(138);
      WriteValue(EncodableValue(std::any_cast<LifecycleSnapshot>(*custom_value).ToEncodableList()), stream);
      return;
    }
  }
  ::flutter::StandardCodecSerializer::WriteValue(value, stream);
}

