// Sets up an instance of `WindowProbeHostApi` to handle messages through the `binary_messenger`.
void WindowProbeHostApi::SetUp(
  ::flutter::BinaryMessenger* binary_messenger,
  WindowProbeHostApi* api) {
  WindowProbeHostApi::SetUp(binary_messenger, api, "");
}

void WindowProbeHostApi::SetUp(
  ::flutter::BinaryMessenger* binary_messenger,
  WindowProbeHostApi* api,
  const std::string& message_channel_suffix) {
  const std::string prepended_suffix = message_channel_suffix.length() > 0 ? std::string(".") + message_channel_suffix : "";
  {
    BasicMessageChannel<> channel(binary_messenger, "dev.flutter.pigeon.mystia_steward_companion_window_probe.WindowProbeHostApi.execute" + prepended_suffix, &GetCodec());
    if (api != nullptr) {
      channel.SetMessageHandler([api](const EncodableValue& message, const ::flutter::MessageReply<EncodableValue>& reply) {
        try {
          const auto& args = std::get<EncodableList>(message);
          const auto& encodable_command_arg = args.at(0);
          if (encodable_command_arg.IsNull()) {
            reply(WrapError("command_arg unexpectedly null."));
            return;
          }
          const auto& command_arg = std::any_cast<const ProbeCommand&>(std::get<CustomEncodableValue>(encodable_command_arg));
          api->Execute(command_arg, [reply](ErrorOr<ProbeSnapshot>&& output) {
            if (output.has_error()) {
              reply(WrapError(output.error()));
              return;
            }
            EncodableList wrapped;
            wrapped.push_back(CustomEncodableValue(std::move(output).TakeValue()));
            reply(EncodableValue(std::move(wrapped)));
          });
        } catch (const std::exception& exception) {
          reply(WrapError(exception.what()));
        }
      });
    } else {
      channel.SetMessageHandler(nullptr);
    }
  }
}

EncodableValue WindowProbeHostApi::WrapError(std::string_view error_message) {
  return EncodableValue(EncodableList{
    EncodableValue(std::string(error_message)),
    EncodableValue("Error"),
    EncodableValue()
  });
}

EncodableValue WindowProbeHostApi::WrapError(const FlutterError& error) {
  return EncodableValue(EncodableList{
    EncodableValue(error.code()),
    EncodableValue(error.message()),
    error.details()
  });
}

